import React, { useState } from 'react';

const AracKontrol = (araclar) => {
  const [aracTipi, setAracTipi] = useState('');
  const [baslangicTarihi, setBaslangicTarihi] = useState('');
  const [bitisTarihi, setBitisTarihi] = useState('');
  const [minFiyat, setMinFiyat] = useState('');
  const [maxFiyat, setMaxFiyat] = useState('');

  // Örnek araç verileri
  const aracler = [
    { id: 1, marka: 'BMW', model: '3 Serisi', tip: 'Sedan', yil: 2022, yakit: 'Dizel', vites: 'Otomatik', fiyat: 1200, resim: 'https://images.unsplash.com/photo-1549399542-7e3f8b79c341?w=400' },
    { id: 2, marka: 'Mercedes', model: 'C Class', tip: 'Sedan', yil: 2023, yakit: 'Benzinli', vites: 'Otomatik', fiyat: 1500, resim: 'https://images.unsplash.com/photo-1550355291-bbee04a92027?w=400' },
    { id: 3, marka: 'Audi', model: 'A4', tip: 'Sedan', yil: 2022, yakit: 'Dizel', vites: 'Otomatik', fiyat: 1300, resim: 'https://images.unsplash.com/photo-1542362567-b07e54358753?w=400' },
    { id: 4, marka: 'Toyota', model: 'Corolla', tip: 'Hatchback', yil: 2021, yakit: 'Benzinli', vites: 'Otomatik', fiyat: 800, resim: 'https://images.unsplash.com/photo-1621007947382-bb3c3968e3bb?w=400' },
    { id: 5, marka: 'Ford', model: 'Focus', tip: 'Hatchback', yil: 2020, yakit: 'Dizel', vites: 'Manuel', fiyat: 700, resim: 'https://images.unsplash.com/photo-1541899481282-d53bffe3c35d?w=400' },
    { id: 6, marka: 'Volkswagen', model: 'Golf', tip: 'Hatchback', yil: 2023, yakit: 'Benzinli', vites: 'Otomatik', fiyat: 900, resim: 'https://images.unsplash.com/photo-1541963463532-d68292c34b19?w=400' }
  ];

  // Filtreleme fonksiyonu
  const filtresizAraclar = (aracListesi) => {
    return aracListesi.filter(arac => {
      if (aracTipi && arac.tip !== aracTipi) return false;
      if (minFiyat && arac.fiyat < minFiyat) return false;
      if (maxFiyat && arac.fiyat > maxFiyat) return false;
      return true;
    });
  };

  const guncelAraclar = filtresizAraclar(araclar);

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="container mx-auto px-4">
        {/* Başlık */}
        <h1 className="text-4xl font-bold text-center mb-8">Araç Kirala</h1>

        {/* Filtre Formu */}
        <div className="bg-white p-6 rounded-lg shadow-md mb-8">
          <form className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {/* Araç Tipi */}
            <div>
              <label className="block text-gray-700 mb-2">Araç Tipi</label>
              <select 
                value={aracTipi} 
                onChange={(e) => setAracTipi(e.target.value)}
                className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="">Tümü</option>
                <option value="Sedan">Sedan</option>
                <option value="Hatchback">Hatchback</option>
                <option value="SUV">SUV</option>
              </select>
            </div>

            {/* Başlangıç Tarihi */}
            <div>
              <label className="block text-gray-700 mb-2">Başlangıç Tarihi</label>
              <input 
                type="date" 
                value={baslangicTarihi}
                onChange={(e) => setBaslangicTarihi(e.target.value)}
                className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            {/* Bitiş Tarihi */}
            <div>
              <label className="block text-gray-700 mb-2">Bitiş Tarihi</label>
              <input 
                type="date" 
                value={bitisTarihi}
                onChange={(e) => setBitisTarihi(e.target.value)}
                className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            {/* Fiyat Aralığı */}
            <div className="grid grid-cols-2 gap-2">
              <input 
                type="number" 
                placeholder="Min Fiyat"
                value={minFiyat}
                onChange={(e) => setMinFiyat(e.target.value)}
                className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
              <input 
                type="number" 
                placeholder="Max Fiyat"
                value={maxFiyat}
                onChange={(e) => setMaxFiyat(e.target.value)}
                className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          </form>

          {/* Filtrele Butonu */}
          <button 
            onClick={() => console.log('Filtreleniyor...')}
            className="mt-4 bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 transition w-full md:w-auto"
          >
            Araçları Filtrele
          </button>
        </div>

        {/* Araç Listesi */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {guncelAraclar.map(arac => (
            <div key={arac.id} className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition">
              <img src={arac.resim} alt={'\${arac.marka} \${arac.model}'} className="w-full h-48 object-cover" />
              <div className="p-4">
                <h3 className="text-xl font-semibold mb-2">{arac.marka} {arac.model}</h3>
                <p className="text-gray-600 mb-2">{arac.yil} • {arac.yakit} • {arac.vites}</p>
                <p className="text-blue-600 font-bold mb-4">₺{arac.fiyat}/gün</p>
                <button className="w-full bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 transition">
                  Detayları Gör
                </button>
              </div>
            </div>
          ))}
        </div>

        {/* Sonuç Yoksa Mesaj */}
        {guncelAraclar.length === 0 && (
          <div className="text-center py-12">
            <p className="text-gray-600 text-lg">Seçtiğiniz kriterlere uygun araç bulunamadı.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default AracKontrol;
